SECTORS = {'A': 0.9, 'B': 0.6, 'C': 0.95, 'D': 0.4}
THRESHOLD = 0.8
for k, v in SECTORS.items():
    print('Sector %s coverage: %.0f percent %s' % (k, v * 100, 'OK' if v >= THRESHOLD else 'BELOW THRESHOLD'))
print('Sectors below threshold: %d' % sum(1 for v in SECTORS.values() if v < THRESHOLD))
print('Note: model coverage only; real coverage needs the system inventory.')
